'use strict';
const $=s=>document.querySelector(s);
let items=[],selectedImage='',current=null,setup=false,busy=false;
const token=new URLSearchParams(location.hash.slice(1)).get('setup');
if(token){$('#setup-key').value=token;history.replaceState(null,'',location.pathname);}
async function api(url,options={}){const r=await window.shopRequest(url,{...options,headers:{'Content-Type':'application/json',...options.headers}});const value=await r.json();if(!r.ok){if(r.status===401&&url!=='/api/login'){ $('#editor').close();await session(); }throw Error(value.error||'Opération impossible.');}return value;}
function notice(message){clearTimeout(notice.timer);$('#notice').textContent=message;notice.timer=setTimeout(()=>{$('#notice').textContent='';},3000);}
async function session(){const s=await api('/api/session');setup=s.needsSetup;$('#admin-greeting').textContent=s.authenticated?'Bonjour, '+(s.username||'Administrateur'):'';$('#auth').hidden=s.authenticated;$('#dashboard').hidden=!s.authenticated;$('#logout').hidden=!s.authenticated;$('#key-label').hidden=!setup||!!token;$('#setup-key').required=setup;$('#password').minLength=setup?12:1;if(window.SHOP_CLOUD){$('#username').type='email';$('#username').autocomplete='email';$('#username').maxLength=254;$('#username').previousSibling.textContent='Adresse e-mail';}$('#password').autocomplete=setup?'new-password':'current-password';$('#auth-title').textContent=setup?'Créer votre accès admin':'Connexion';$('#auth-help').textContent=setup?'Choisissez un identifiant et un mot de passe d’au moins 12 caractères. Si un code est demandé, lancez LANCER.cmd dans le dossier du projet.':'Connectez-vous pour gérer votre catalogue.';$('#login-button').textContent=setup?'Créer mon compte':'Se connecter';if(s.authenticated)await load();}
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();$('#auth-error').textContent='';$('#login-button').disabled=true;try{const credentials={username:$('#username').value.trim(),password:$('#password').value};if(setup)await api('/api/setup',{method:'POST',body:JSON.stringify({...credentials,key:$('#setup-key').value})});await api('/api/login',{method:'POST',body:JSON.stringify(credentials)});$('#password').value='';$('#setup-key').value='';await session();notice('Vous êtes connecté.');}catch(e){$('#auth-error').textContent=e.message;}finally{$('#login-button').disabled=false;}});
$('#logout').addEventListener('click',async()=>{try{await api('/api/logout',{method:'POST',body:'{}'});await session();notice('Vous êtes déconnecté.');}catch(e){notice(e.message);}});
async function load(){items=await api('/api/admin/products'+($('#list-mode').value==='deleted'?'?deleted=1':''));render();}
function render(){const query=$('#admin-search').value.toLocaleLowerCase();$('#count').textContent=$('#list-mode').value==='deleted'?`${items.length} pièces dans la corbeille`:`${items.length} pièces · ${items.filter(p=>p.active).length} visibles`;const list=items.filter(p=>`${p.name} ${p.ref} ${p.category}`.toLocaleLowerCase().includes(query));$('#admin-products').replaceChildren();for(const p of list){const row=document.createElement('article');row.className='row';const image=document.createElement('img');image.src=p.image;image.alt='';image.loading='lazy';const info=document.createElement('div');info.className='row-info';const title=document.createElement('h2');title.textContent=p.name;const meta=document.createElement('p');meta.textContent=`${p.ref||'APM-'+p.id} · ${p.category} · ${p.price===null?'Prix sur demande':p.price+' MAD'} · ${p.availability}`;const badge=document.createElement('span');badge.className='badge'+(p.active?'':' hidden');badge.textContent=p.efface==='Oui'?'Supprimée le '+new Date(p.date_suppression).toLocaleString('fr-FR',{timeZone:'Africa/Casablanca'}):p.active?'Visible':'Masquée';const edit=document.createElement('button');edit.textContent='Modifier';edit.setAttribute('aria-label','Modifier '+p.name);edit.onclick=()=>openEditor(p);info.append(title,meta,badge);const remove=document.createElement('button');remove.textContent='Supprimer';remove.className='danger';remove.setAttribute('aria-label','Supprimer '+p.name);remove.onclick=()=>requestDelete(p);if(p.efface==='Oui'){const restore=document.createElement('button');restore.textContent='Restaurer';restore.onclick=async()=>{restore.disabled=true;try{await api('/api/admin/products/'+p.id+'/restore',{method:'POST',body:JSON.stringify({version:p.version})});await load();notice('Pièce restaurée et masquée. Vous pouvez la rendre visible dans le catalogue.');}catch(e){notice(e.message);restore.disabled=false;}};remove.textContent='Supprimer définitivement';remove.setAttribute('aria-label','Supprimer définitivement '+p.name);row.append(image,info,restore,remove);}else row.append(image,info,edit,remove);$('#admin-products').append(row);}if(!list.length){const p=document.createElement('p');p.className='empty';p.textContent='Aucune pièce trouvée.';$('#admin-products').append(p);}}
$('#admin-search').addEventListener('input',render);$('#refresh').addEventListener('click',()=>load().catch(e=>notice(e.message)));$('#new-product').addEventListener('click',()=>openEditor());
function openEditor(p){current=p||null;$('#product-form').reset();$('#editor-error').textContent='';$('#image-status').textContent='';$('#editor-title').textContent=p?'Modifier la pièce':'Ajouter une pièce';for(const key of ['name','ref','category','description'])$('#'+key).value=p?.[key]||'';$('#active').checked=p?!!p.active:true;selectedImage=p?.image||'';preview();$('#editor').showModal();}
function preview(){const value=selectedImage;$('#image-preview').hidden=!value;if(value)$('#image-preview').src=value;else $('#image-preview').removeAttribute('src');}

function closeEditor(){if(!busy)$('#editor').close();}$('#close-editor').onclick=closeEditor;$('#cancel-editor').onclick=closeEditor;$('#editor').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
function setBusy(value){busy=value;$('#product-form').querySelectorAll('button,input,select,textarea').forEach(el=>el.disabled=value);$('#close-editor').disabled=value;}
$('#image-file').addEventListener('change',async()=>{const file=$('#image-file').files[0];if(!file)return;$('#editor-error').textContent='';setBusy(true);try{if(file.size>5*1024*1024)throw Error('Photo trop volumineuse : 5 Mo maximum.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choisissez une photo JPEG, PNG ou WebP.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Impossible de lire la photo.'));reader.readAsDataURL(file);});const image=await createImageBitmap(file);image.close();const result=await api('/api/admin/upload',{method:'POST',body:JSON.stringify({content})});selectedImage=result.image;preview();$('#image-status').textContent='Photo importée. Enregistrez la pièce pour l’utiliser.';}catch(e){$('#editor-error').textContent=e.message;}finally{setBusy(false);$('#image-file').value='';}});
$('#product-form').addEventListener('submit',async e=>{e.preventDefault();$('#editor-error').textContent='';if(!selectedImage){$('#editor-error').textContent='Importez une photo.';return;}const value={};for(const key of ['name','ref','category','description'])value[key]=$('#'+key).value;value.price=current?.price??null;value.availability=current?.availability||'Sur demande';value.active=$('#active').checked;value.image=selectedImage;value.version=current?.version;setBusy(true);try{await api('/api/admin/products'+(current?'/'+current.id:''),{method:current?'PUT':'POST',body:JSON.stringify(value)});$('#editor').close();await load();notice('Pièce enregistrée. Actualisez la boutique pour voir le changement.');}catch(e){$('#editor-error').textContent=e.message;}finally{setBusy(false);}});
if(location.protocol==='file:')notice('Lancez LANCER.cmd puis ouvrez http://127.0.0.1:4174/admin.html pour utiliser l’administration.');else session().catch(e=>notice('Connexion au serveur impossible : '+e.message));

let deleting=null,deleteBusy=false;
function requestDelete(p){deleting=p;const permanent=p.efface==='Oui';$('#delete-title').textContent=permanent?'Supprimer définitivement cette pièce ?':'Supprimer la pièce ?';$('#delete-help').textContent=permanent?'Cette action efface la fiche de la base de données. Elle ne pourra plus être restaurée.':'La pièce sera conservée dans la corbeille avec sa date de suppression.';$('#confirm-delete').textContent=permanent?'Supprimer définitivement':'Déplacer dans la corbeille';$('#delete-description').textContent=p.name+' — '+(p.ref||'APM-'+p.id);$('#delete-error').textContent='';$('#delete-dialog').showModal();$('#cancel-delete').focus();}
$('#cancel-delete').onclick=()=>{if(!deleteBusy)$('#delete-dialog').close();};
$('#delete-dialog').addEventListener('cancel',e=>{if(deleteBusy)e.preventDefault();});
$('#confirm-delete').onclick=async()=>{if(!deleting||deleteBusy)return;deleteBusy=true;$('#confirm-delete').disabled=true;$('#cancel-delete').disabled=true;try{await api('/api/admin/products/'+deleting.id+(deleting.efface==='Oui'?'/permanent':''),{method:'DELETE',body:JSON.stringify({version:deleting.version})});$('#delete-dialog').close();await load();notice(deleting.efface==='Oui'?'Pièce supprimée définitivement.':'Pièce déplacée dans la corbeille.');}catch(e){$('#delete-error').textContent=e.message;}finally{deleteBusy=false;$('#confirm-delete').disabled=false;$('#cancel-delete').disabled=false;}};

$('#list-mode').addEventListener('change',()=>load().catch(e=>notice(e.message)));
